import * as THREE from 'three';
import {createExerciseCycle} from './exercise-cycle.js';
import {createBoxingModel} from './boxing-model.js';
import {createBoxingSession,fitBoxingCamera} from './boxing-session.js';
export const BOXING_BODY=`<div class="gym-layout"><div class="gym-court" id="boxing-court" role="img" aria-label="도름이가 샌드백에 왼손과 오른손을 번갈아 대고 옆으로 피하는 모습" tabindex="0"></div><section class="gym-panel boxing-panel" id="boxing-panel"><p id="boxing-status" role="status"></p><label>연습 방법 <select id="boxing-mode"><option value="easy">편하게 운동 · 자동 샌드백</option><option value="hold">누르는 동안 번갈아 연습</option><option value="manual">왼손 · 오른손 · 피하기 직접 고르기</option></select></label><label class="gym-repeat" for="boxing-repeat"><input id="boxing-repeat" type="checkbox">5초 쉬었다가 반복</label><div class="gym-actions gym-exercise-actions"><button id="boxing-start">연습 시작</button><button id="boxing-pause">잠깐 멈추기</button><button id="boxing-stop">운동 멈추기</button><button id="boxing-exit">멈추고 나오기</button></div><div class="boxing-cue" id="boxing-cue" aria-hidden="true"><span id="boxing-cue-fill"></span><i></i></div><p id="boxing-beat"></p><div class="gym-hold" id="boxing-manual-controls"><button id="boxing-left">왼손</button><button id="boxing-right">오른손</button><button id="boxing-dodge">옆으로 피하기</button></div><div class="gym-hold" id="boxing-hold-controls"><button id="boxing-hold">누르는 동안 연습</button></div><p id="boxing-score" role="status"></p><details id="boxing-options"><summary>연습 설정</summary><label>짧은 연습 <select id="boxing-rounds"><option value="1">4번 치고 피하기</option><option value="2" selected>8번 치고 두 번 피하기</option><option value="3">12번 치고 세 번 피하기</option></select></label></details><details id="boxing-help"><summary>안내 보기</summary><p>편하게 운동은 시작을 누르면 자동으로 움직여요. 반복을 고르면 움직임을 마치고 두 발을 딛은 채 5초 쉬고 다시 운동해요. 반복은 처음에는 꺼져 있어요.</p><p>운동 멈추기는 다음 반복을 취소하고 안전하게 멈춰요. 잠깐 멈추기나 화면을 떠나기도 반복을 취소해요. 계속하기는 현재 운동만 이어가요.</p><p>혼자 샌드백을 연습해요. 왼손 · 오른손을 번갈아 네 번 친 뒤 옆으로 피하고 돌아와요.</p><p>직접 고르기는 ← 왼손 · → 오른손 · ↓ 피하기예요. 표시가 가운데에 닿기 조금 전에 누르면 손이 뻗어 샌드백에 닿아요. 손이 실제로 닿은 횟수와 그 순간의 박자만 기록해요. 놓쳐도 바로 다음 차례를 연습하면 돼요.</p><p>길게 누르기는 스페이스를 써요. 안내를 접어도 연습은 계속돼요. 나가면 손과 샌드백을 멈추고 걸어 나와요. 보상이나 저장되는 연속 기록은 없어요.</p></details></section></div>`;
export function createBoxingController({ui,getView,getActors,stage,isAllowed=()=>true,onChange=()=>{},clearInput=()=>{},doc=globalThis.document,win=globalThis.window,sessionFactory=createBoxingSession,modelFactory=createBoxingModel,fitCamera=fitBoxingCamera}){
 const camera=new THREE.OrthographicCamera(),$=id=>doc.querySelector('#'+id);let live=null,pending=false,generation=0;
 function listen(node,type,fn,opts){if(!node)return;const token=generation,guarded=e=>{if(token===generation&&live)fn(e);};node.addEventListener(type,guarded,opts);live.listeners.push([node,type,guarded,opts]);}
 function clear(){clearInput();if(!live)return;live.pointers.clear();live.keys.clear();live.model.setInput({held:false});}
 function held(){if(live)live.model.setInput({held:live.pointers.size>0||live.keys.size>0});}
 function render(){if(!live)return;const s=live.model.snapshot(),p=live.session.phase,paused=live.suspended||s.paused,cycle=live.cycle.snapshot(),ready=live.session.ready&&['idle','ready','stopped'].includes(s.state),cue=s.expected==='dodge'?'옆으로 피하기':s.expected==='left'?'왼손':'오른손';$('boxing-status').textContent=paused?'멈췄어요. 계속하기는 현재 운동만 이어가요':p==='boarding'?'멈춘 샌드백 앞으로 걸어가요':p==='guarding'?'두 발을 딛고 손을 준비해요':p==='lowering'||p==='exiting'?'샌드백이 멈췄어요. 천천히 걸어 나와요':live.exiting?'손과 샌드백을 천천히 멈추고 있어요':cycle.phase==='rest'?`두 발을 딛고 쉬어요 · ${Math.ceil(cycle.remaining)}초 뒤 자동으로 운동해요`:ready?'준비됐어요. 시작은 직접 골라요':cue+' 차례';$('boxing-score').textContent=`샌드백 맞히기 ${s.contacts}회 · 박자 ${s.score}% · 피하고 돌아오기 ${s.dodges}회`;$('boxing-beat').textContent=s.state==='active'?`${cue} · 남은 ${Math.ceil(s.remaining)}초`:s.state==='stopped'?`이번 연습 ${s.contacts} / ${s.rounds*4}회 닿았어요`: '샌드백은 손이 닿을 때만 살짝 움직여요';if($('boxing-cue-fill').style)$('boxing-cue-fill').style.width=`${Math.min(100,s.beat/1.5*100)}%`;$('boxing-start').disabled=!ready||paused||live.exiting||cycle.phase==='rest';$('boxing-start').textContent=s.state==='stopped'?'한 번 더':'연습 시작';$('boxing-pause').textContent=paused?'계속하기':'잠깐 멈추기';$('boxing-exit').disabled=live.exiting;$('boxing-stop').disabled=live.exiting||paused||(!cycle.enabled&&s.state!=='active');$('boxing-repeat').checked=cycle.enabled;$('boxing-repeat').disabled=live.exiting||paused||s.mode!=='easy';$('boxing-score').hidden=s.mode==='easy';$('boxing-cue').hidden=s.mode==='easy';$('boxing-beat').hidden=s.mode==='easy';for(const id of['boxing-mode','boxing-rounds'])$(id).disabled=!ready||paused||live.exiting;for(const side of['left','right','dodge'])$('boxing-'+side).disabled=s.mode!=='manual'||s.state!=='active'||paused||live.exiting;$('boxing-hold').disabled=s.mode!=='hold'||s.state!=='active'||paused||live.exiting;$('boxing-manual-controls').hidden=s.mode!=='manual';$('boxing-hold-controls').hidden=s.mode!=='hold';}
 function clean({restore}={}){pending=false;generation++;if(!live)return;const old=live;live=null;old.observer?.disconnect();for(const[n,t,f,o]of old.listeners)n.removeEventListener(t,f,o);old.cycle.dispose();old.model.dispose?.();old.session.dispose({restore:restore??(getView()===old.source)});stage.classList.remove('gym-open');doc.body?.classList.remove('gym-open');clearInput();onChange();}
 function cancel(){const owned=!!live||pending;clean();if(owned)ui.close();}
 function close(){if(!live||live.exiting)return;clear();live.cycle.cancel();live.suspended=false;live.model.resume();live.exiting=true;live.model.stop('exit');live.session.requestExit();render();}
 function pause(){if(!live)return;clear();live.cycle.cancel();live.suspended=true;live.model.pause();live.session.pause?.();render();}
 function open(){if(live||pending||!isAllowed())return false;const source=getView();if(!source?.schoolView?.gymView?.boxing)return false;pending=true;const token=++generation;
 const accepted=ui.workshop('복싱 · 혼자 샌드백 연습',BOXING_BODY,()=>{if(token!==generation||!pending)return;if(getView()!==source){pending=false;return;}pending=false;let session;try{session=sessionFactory({view:source,...getActors()});live={session,cycle:createExerciseCycle(),model:modelFactory({mode:'easy',rounds:2}),source,listeners:[],pointers:new Set(),keys:new Set(),suspended:false,exiting:false,fit:''};stage.classList.add('gym-open');doc.body?.classList.add('gym-open');clearInput();onChange();
  const act=(id,fn)=>listen($(id),'click',e=>{if(token!==generation||!live||$(id).disabled)return;if(e.detail>0&&live.cancelledPointer)return;e.preventDefault();fn();});
  act('boxing-start',()=>{clear();if(live.session.ready){live.model.start();live.cycle.start();}render();});act('boxing-stop',()=>{clear();live.cycle.cancel();live.model.stop('manual');render();});act('boxing-exit',close);act('boxing-pause',()=>{if(doc.hidden)return;if(live.suspended||live.model.snapshot().paused){clear();live.suspended=false;live.model.resume();render();}else pause();});
  listen($('boxing-repeat'),'input',()=>{if($('boxing-repeat').disabled)return;live.cycle.setEnabled($('boxing-repeat').checked);if(live.cycle.snapshot().enabled&&live.model.snapshot().state==='active')live.cycle.start();render();});
  for(const id of['boxing-mode','boxing-rounds'])listen($(id),'input',()=>{if($(id).disabled)return;clear();if(id==='boxing-mode')live.cycle.cancel();if(id==='boxing-mode')live.model.setMode($(id).value);else live.model.setRounds(Number($(id).value));render();});
  for(const side of['left','right','dodge'])act('boxing-'+side,()=>{live.model.setInput(side==='dodge'?{dodge:true}:{punch:side});render();});
  const button=$('boxing-hold');listen(button,'pointerdown',e=>{if(button.disabled||e.button!==0||e.isPrimary===false)return;e.preventDefault();live.cancelledPointer=false;button.setPointerCapture?.(e.pointerId);live.pointers.add(e.pointerId);held();});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(button,type,e=>{if(!live)return;if(type!=='pointerup')live.cancelledPointer=true;live.pointers.delete(e.pointerId);held();});
  listen(doc,'keydown',e=>{if(!live||e.repeat||e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const control=e.target?.closest?.('button,a,summary,[role="button"]')??(['BUTTON','A','SUMMARY'].includes(e.target?.tagName)?e.target:null);if(control&&control!==button)return;const s=live.model.snapshot();if(live.suspended||s.paused||live.exiting||s.state!=='active')return;if(e.code==='Space'&&s.mode==='hold'){e.preventDefault();live.keys.add(e.code);held();}else if(s.mode==='manual'&&['ArrowLeft','ArrowRight','ArrowDown'].includes(e.code)){e.preventDefault();live.model.setInput(e.code==='ArrowDown'?{dodge:true}:{punch:e.code==='ArrowLeft'?'left':'right'});render();}});listen(doc,'keyup',e=>{if(live){live.keys.delete(e.code);held();}});
  listen($('boxing-panel'),'pointerdown',()=>{if(live)live.cancelledPointer=false;},true);listen($('boxing-panel'),'pointercancel',()=>{if(live)live.cancelledPointer=true;},true);
  const modal=$('modal'),exit=modal?.querySelector?.('[data-close]');if(exit)exit.onclick=e=>{if(token!==generation||!live)return;e.preventDefault();close();};listen(modal,'cancel',e=>{e.preventDefault();close();});listen(modal,'click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation?.();}},true);
  listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(win,'pagehide',cancel);const resize=()=>{if(live&&token===generation)viewport(stage.clientWidth,stage.clientHeight);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('boxing-court'));}render();resize();$('boxing-court').focus();return()=>{if(token===generation)clean();};
 }catch(error){if(live)clean();else session?.dispose();pending=false;ui.close();ui.toast('샌드백 앞에 빈자리가 필요해요. 잠깐 뒤 다시 해 주세요');}},{kind:'gym-workshop boxing-workshop',closeLabel:'멈추고 나오기'});if(!accepted&&token===generation)pending=false;return accepted;}
 function runtimeFailure(){const restore=!!live&&getView()===live.source;clean({restore});ui.close();ui.toast('샌드백 연습을 멈췄어요. 잠깐 뒤 다시 해 주세요');}
 function tick(dt){if(!live)return;if(getView()!==live.source){clean({restore:false});ui.close();return;}if(doc.hidden){if(!live.suspended)pause();return;}try{const s=live.model.snapshot();if(!live.suspended&&!s.paused){if(live.session.ready&&s.state==='idle')live.model.ready();live.session.tick(dt,live.model);if(live.session.ready&&live.model.snapshot().state==='idle')live.model.ready();if(live.cycle.update(dt,live.model.snapshot(),live.session.ready)&&!live.exiting)live.model.start();}if(live.session.done){clean();ui.close();return;}render();}catch(error){runtimeFailure();}}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('boxing-court').getBoundingClientRect(),a=stage.getBoundingClientRect(),rect={x:Math.max(0,b.left-a.left),y:Math.max(0,b.top-a.top),width:Math.max(1,Math.min(b.width,width)),height:Math.max(1,Math.min(b.height,height))},active=['ready','exercise'].includes(live.session.phase),key=Object.values(rect).join(',')+':'+active;if(key!==live.fit){try{fitCamera(camera,live.session.root,rect,{active});live.fit=key;}catch(error){runtimeFailure();}}return rect;}
 return{open,close,cancel,pause,tick,viewport,camera,dispose:cancel,get active(){return!!live;},snapshot:()=>live?{...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused,cycle:live.cycle.snapshot(),session:live.session.snapshot(),exiting:live.exiting}:null};
}
